Source code in <code>reccy/protocol/ipc.py</code> <pre><code>class ProtocolListener:
    def __init__(
        self,
        conn: Connection,
        *,
        parse: typing.Callable[[str], object],
        version: int,
        peer_role: str,
        local_role: str,
        on_message: typing.Callable[['ProtocolListener', object], None],
        request_shutdown: typing.Callable[[], None] | None = None,
        on_validation_error: typing.Callable[[str], None] | None = None,
        logger: logging.Logger | None = None,
    ) -&gt; None:
        self.conn = conn
        self.parse = parse
        self.version = version
        self.peer_role = peer_role
        self.local_role = local_role
        self.on_message = on_message
        self.request_shutdown = request_shutdown
        self.on_validation_error = on_validation_error
        self.logger = logger or logging.getLogger(__name__)
        self.handshake_complete = False
        self.lock = threading.Lock()
        self._thread: threading.Thread | None = None

    def start(self, *, name: str = 'IpcListener') -&gt; None:
        if self._thread is not None:
            raise RuntimeError('IPC listener has already been started')
        self._thread = threading.Thread(target=self.read, daemon=True, name=name)
        try:
            self._thread.start()
        except RuntimeError:
            self._thread = None
            self.close()
            raise

    def wait_closed(self, timeout: float | None = None) -&gt; bool:
        if self._thread is None:
            raise RuntimeError('IPC listener has not been started')
        if self._thread is threading.current_thread():
            raise RuntimeError('IPC listener cannot wait for itself')
        self._thread.join(timeout)
        return not self._thread.is_alive()

    def write(self, message: str) -&gt; bool:
        with self.lock:
            return self.conn.write(message)

    def write_model(self, message: BaseModel, *, exclude_none: bool = False) -&gt; bool:
        return self.write(message_json(message, exclude_none=exclude_none))

    def close(self) -&gt; None:
        self.conn.close()

    def read(self) -&gt; None:
        handshake_timer = threading.Timer(HANDSHAKE_TIMEOUT, self.close)
        handshake_timer.start()
        try:
            lines = iter(self.conn.read_lines(max_bytes=MAX_IPC_MESSAGE_BYTES))
            while True:
                try:
                    line = next(lines)
                except StopIteration:
                    return
                except (UnicodeError, ValueError) as error:
                    self.logger.warning('Closing malformed IPC connection: %s', error)
                    if self.on_validation_error is not None:
                        self.on_validation_error(str(error))
                    return
                try:
                    message = self.parse(line)
                except ValidationError as e:
                    self.logger.warning('Ignoring malformed IPC message')
                    if self.on_validation_error is not None:
                        self.on_validation_error(str(e))
                    continue
                if isinstance(message, Hello):
                    if not self.receive_hello(message):
                        return
                    handshake_timer.cancel()
                    continue
                if not self.handshake_complete:
                    self.reject(
                        f'{self.peer_role} hello required before other messages'
                    )
                    return
                if isinstance(message, Shutdown):
                    if self.request_shutdown:
                        self.request_shutdown()
                    continue
                self.on_message(self, message)
        finally:
            handshake_timer.cancel()
            self.close()

    def receive_hello(self, message: Hello) -&gt; bool:
        if message.version != self.version:
            error = (
                f'{self.peer_role} protocol version {message.version} is not '
                f'supported; {self.local_role} requires {self.version}'
            )
            self.reject(error)
            return False
        self.handshake_complete = True
        self.write_model(
            Hello(type='hello', role=self.local_role, version=self.version)
        )
        return True

    def reject(self, message: str) -&gt; None:
        self.write_model(Error(type='error', message=message))
        self.close()
</code></pre>

